/// One `[Keyword_N]` section of an Xshell `.hls` highlight set (UTF-16LE INI).
public struct HighlightKeyword: Equatable, Sendable {
    public var pattern: String
    public var description: String
    public var useRegex: Bool
    public var caseSensitive: Bool
    public var enabled: Bool
    public var bold: Bool, italic: Bool, underline: Bool, strikeout: Bool
    /// Raw color indices as stored (observed 281–288). Their mapping to the `[Colors]` palette is inferred, not verified: index - 281 looked up in the palette.
    public var textColorIndex: Int
    public var backColorIndex: Int
    /// `TermBackColor=1` presumably means "keep the terminal background"; unverified.
    public var termBackColor: Bool
}

public struct HighlightSet: Equatable, Sendable {
    public var name: String
    public var version: String?
    public var keywords: [HighlightKeyword]
    /// `[Colors] Colors=` as 16 RRGGBB values.
    public var palette: [RGB]

    public init(data: Data, name: String) throws {
        let (text, _) = try IniText.decode(data)
        let sections = IniText.parse(text)
        self.name = name
        self.version = sections.first { $0.name == "info" }?.value("Version")
        let colors = sections.first { $0.name == "Colors" }?.value("Colors") ?? ""
        self.palette = try colors.split(separator: ",").map { s in
            guard let c = RGB(hex: s.lowercased()) else { throw XshellFormatError.invalidColor(key: "Colors", value: String(s)) }
            return c
        }
        func int(_ s: IniSection, _ k: String) -> Int { Int(s.value(k) ?? "") ?? 0 }
        self.keywords = sections
            .filter { $0.name.hasPrefix("Keyword_") }
            .sorted { (Int($0.name.dropFirst(8)) ?? 0) < (Int($1.name.dropFirst(8)) ?? 0) }
            .map { s in
                HighlightKeyword(pattern: s.value("Keyword") ?? "", description: s.value("Description") ?? "",
                                 useRegex: int(s, "UseRegex") == 1, caseSensitive: int(s, "CaseSens") == 1, enabled: int(s, "Enable") == 1,
                                 bold: int(s, "Bold") == 1, italic: int(s, "Italic") == 1, underline: int(s, "Underline") == 1, strikeout: int(s, "Strikeout") == 1,
                                 textColorIndex: int(s, "TextColorIndex"), backColorIndex: int(s, "BackColorIndex"), termBackColor: int(s, "TermBackColor") == 1)
            }
        if let count = sections.first(where: { $0.name == "info" })?.value("Count"), Int(count) != keywords.count {
            throw XshellFormatError.missingKey("Keyword_\(keywords.count) (info Count=\(count))")
        }
    }

    public init(contentsOf url: URL) throws { try self.init(data: Data(contentsOf: url), name: url.deletingPathExtension().lastPathComponent) }

    public struct Match: Equatable, Sendable { public var keyword: Int; public var start: Int; public var length: Int }

    /// Matches enabled keywords against one line. Ranges are UTF-16 offsets. A keyword whose regex does not compile is returned in `invalid`.
    /// Uses ICU regular expressions (NSRegularExpression); Xshell's regex engine was not identified, so dialect differences are possible.
    public func matches(in line: String) -> (matches: [Match], invalid: [Int]) {
        var out: [Match] = [], invalid: [Int] = []
        let ns = line as NSString
        for (i, k) in keywords.enumerated() where k.enabled && !k.pattern.isEmpty {
            let pattern = k.useRegex ? k.pattern : NSRegularExpression.escapedPattern(for: k.pattern)
            guard let re = try? NSRegularExpression(pattern: pattern, options: k.caseSensitive ? [] : [.caseInsensitive]) else { invalid.append(i); continue }
            for m in re.matches(in: line, range: NSRange(location: 0, length: ns.length)) where m.range.length > 0 {
                out.append(Match(keyword: i, start: m.range.location, length: m.range.length))
            }
        }
        return (out, invalid)
    }

    /// Inferred color lookup (see `HighlightKeyword.textColorIndex`).
    public func color(index: Int) -> RGB? { let i = index - 281; return palette.indices.contains(i) ? palette[i] : nil }
}

// Feature entry: payload is JSON {"path": "...", "text": "..."?}. An empty payload reports readiness.
public enum HighlightFeature: CarveFeature {
    public static let id = "highlight"
    public static let contractSha256 = "c69bc213e79252eddd5ba698c7e4c69c1b55703c9ef3e1d96db1e7bdfbd89aef"
    public static let dependsOn: [String] = ["formats"]

    public static func run(_ request: FeatureRequest, dependencies: FeatureOutputs) throws -> FeatureResponse {
        if request.payload.isEmpty { return FeatureResponse(payload: #"{"ready":true}"#) }
        guard let obj = try JSONSerialization.jsonObject(with: Data(request.payload.utf8)) as? [String: String], let path = obj["path"] else {
            throw FeatureError.failed(id, "expected JSON {path, text?}")
        }
        let set = try HighlightSet(contentsOf: URL(fileURLWithPath: path))
        var out: [String: Any] = ["name": set.name, "palette": set.palette.map(\.hex),
                                  "keywords": set.keywords.map { ["pattern": $0.pattern, "description": $0.description, "enabled": $0.enabled, "regex": $0.useRegex] }]
        if let text = obj["text"] {
            let r = set.matches(in: text)
            out["matches"] = r.matches.map { ["keyword": $0.keyword, "start": $0.start, "length": $0.length] }
            out["invalidKeywords"] = r.invalid
        }
        return FeatureResponse(payload: String(decoding: try JSONSerialization.data(withJSONObject: out, options: [.sortedKeys]), as: UTF8.self))
    }
}
